}$u=current_user();$result=null;$title='';$desc='';$local=0;
if($_SERVER['REQUEST_METHOD']==='POST'){$title=trim((string)($_POST['titulo']??''));$desc=trim((string)($_POST['descricao']??''));$local=(int)($_POST['local_id']??0);$result=geop_v8_ai_assist($pdo,$title,$desc,$local);geop_v8_record_ai_analysis($pdo,null,(int)$u['id'],'ASSISTENCIA_ABERTURA',$result,$title.' '.$desc);}
