<div class="card mb-3"><div class="card-body"><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="col-md-8"><label class="form-label">Título</label><input class="form-control" name="titulo" value="<?=e($title)?>" required></div><div class="col-md-4"><label class="form-label">Local</label><select class="form-select" name="local_id"><option value="0">Não informado</option><?php foreach($locals as $l):?><option value="<?=(int)$l['id']?>" <?= $local===(int)$l['id']?'selected':''?>><?=e($l['nome'])?></option><?php endforeach?></select></div><div class="col-12"><label class="form-label">Descrição</label><textarea class="form-control" name="descricao" rows="5" required><?=e($desc)?></textarea></div><div class="col-12"><button class="btn btn-primary">Analisar</button></div></form></div></div>
<?php if($result):?><div class="row g-3"><div class="col-md-4"><div class="card h-100"><div class="card-body"><h2 class="h5">Prioridade sugerida</h2><div class="display-6"><?=e($result['prioridade_sugerida'])?></div></div></div></div><div class="col-md-4"><div class="card h-100"><div class="card-body"><h2 class="h5">Categorias</h2><?php foreach($result['categorias_sugeridas'] as $c):?><div class="border-bottom py-2"><?=e($c['nome'])?> <span class="badge text-bg-secondary"><?=e((string)$c['score'])?></span></div><?php endforeach?><?php if(!$result['categorias_sugeridas']):?><div class="text-muted">Sem sugestão forte.</div><?php endif?></div></div></div><div class="col-md-4"><div class="card h-100"><div class="card-body"><h2 class="h5">Materiais possíveis</h2><?php foreach($result['materiais_sugeridos'] as $m):?><div class="border-bottom py-2"><?=e($m['nome'])?><div class="small text-muted">R$ <?=e(number_format((float)$m['custo_unitario'],2,',','.'))?> / <?=e($m['unidade']??'')?></div></div><?php endforeach?><?php if(!$result['materiais_sugeridos']):?><div class="text-muted">Nenhum item de estoque claramente relacionado.</div><?php endif?></div></div></div></div><div class="card mt-3"><div class="card-body"><h2 class="h5">Possíveis OS duplicadas</h2><?php foreach($result['duplicidades'] as $d):?><div class="border rounded p-2 mb-2"><a href="<?=e(app_path('ordem_detalhe',['id'=>$d['id']]))?>"><strong><?=e($d['numero_os'])?></strong> — <?=e($d['titulo'])?></a><div class="small text-muted">Status <?=e($d['status'])?> · similaridade <?=e(number_format($d['similaridade']*100,0))?>%</div></div><?php endforeach?><?php if(!$result['duplicidades']):?><div class="text-muted">Nenhuma duplicidade relevante encontrada.</div><?php endif?></div></div><?php endif?>
